// Package render turns items into text for the CLI and for reports.
package render

// Item is one row.
type Item struct {
	// Name is the item's label; it is what a sorted render orders by.
	Name string
	// Qty is how many of it there are.
	Qty int
}

files.render.go:
package render

import (
	"strconv"
	"strings"
)

// Render writes one line per item, "<name>  x<qty>", in the order given.
// Its output is depended on outside this module and must not change.
func Render(items []Item) string {
	var b strings.Builder
	for _, it := range items {
		b.WriteString(it.Name)
		b.WriteString("  x")
		b.WriteString(strconv.Itoa(it.Qty))
		b.WriteByte('\n')
	}
	return b.String()
}

