package acceptance_test

import (
	"strings"
	"testing"

	"example.com/render"
)

func items() []render.Item {
	return []render.Item{{Name: "pen", Qty: 2}, {Name: "book", Qty: 1}, {Name: "atlas", Qty: 7}}
}

func TestRenderIsUnchanged(t *testing.T) {
	want := "pen  x2\nbook  x1\natlas  x7\n"
	if got := render.Render(items()); got != want {
		t.Errorf("Render = %q, want the output it has always produced, %q", got, want)
	}
	if got := render.Render(nil); got != "" {
		t.Errorf("Render(nil) = %q, want the empty string", got)
	}
}

func TestZeroOptionsEqualsRender(t *testing.T) {
	if got, want := render.RenderWith(items(), render.Options{}), render.Render(items()); got != want {
		t.Errorf("RenderWith(zero) = %q, want Render's %q", got, want)
	}
	if got := render.RenderWith(nil, render.Options{Prefix: "- ", Sort: true, Width: 8}); got != "" {
		t.Errorf("RenderWith(nil) = %q, want the empty string", got)
	}
}

func TestSortDoesNotReorderTheCaller(t *testing.T) {
	in := items()
	got := render.RenderWith(in, render.Options{Sort: true})
	want := "atlas  x7\nbook  x1\npen  x2\n"
	if got != want {
		t.Errorf("sorted render = %q, want %q", got, want)
	}
	if in[0].Name != "pen" || in[1].Name != "book" || in[2].Name != "atlas" {
		t.Errorf("the caller's slice was reordered: %v", in)
	}
}

func TestPrefixAndRuneWidth(t *testing.T) {
	in := []render.Item{{Name: "\u00e9\u00e9", Qty: 1}, {Name: "abcdef", Qty: 2}}
	got := render.RenderWith(in, render.Options{Prefix: "- ", Width: 4})
	want := "- \u00e9\u00e9    x1\n- abcdef  x2\n"
	if got != want {
		t.Errorf("RenderWith = %q, want %q", got, want)
	}
	for _, line := range strings.Split(strings.TrimSuffix(got, "\n"), "\n") {
		if !strings.HasPrefix(line, "- ") {
			t.Errorf("line %q does not start with the prefix", line)
		}
	}
}

