package render

import (
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Options tune a render. The zero value renders exactly as Render does.
type Options struct {
	// Prefix is written in front of every line.
	Prefix string
	// Sort renders the items ordered by Name rather than as given.
	Sort bool
	// Width pads the name column to that many runes; 0 means no padding.
	Width int
}

// Render writes one line per item, "<name>  x<qty>", in the order given.
// Its output is depended on outside this module and must not change; it
// is RenderWith with the zero Options and stays that way.
func Render(items []Item) string {
	return RenderWith(items, Options{})
}

// RenderWith writes one line per item under opts. The caller's slice is
// never reordered: a sorted render works on a copy.
func RenderWith(items []Item, opts Options) string {
	if opts.Sort {
		sorted := make([]Item, len(items))
		copy(sorted, items)
		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Name < sorted[j].Name })
		items = sorted
	}
	var b strings.Builder
	for _, it := range items {
		b.WriteString(opts.Prefix)
		b.WriteString(it.Name)
		if pad := opts.Width - utf8.RuneCountInString(it.Name); pad > 0 {
			b.WriteString(strings.Repeat(" ", pad))
		}
		b.WriteString("  x")
		b.WriteString(strconv.Itoa(it.Qty))
		b.WriteByte('\n')
	}
	return b.String()
}

